#!/system/bin/sh
# ============================================================
# patch-fix-approval-notify.sh — DSHA 极速热更新增量补丁
# 修复内容：
# 1. 消除授权时通知栏与灵动岛误弹“任务已完成”；
# 2. 消除手机端审批后 Web 端黄色授权弹窗滞留问题。
# ============================================================
set -eu

ROOTFS="${1:-/data/adb/dsha/rootfs}"
DATA_DIR="${2:-/data/adb/dsha}"

echo "==> [增量补丁] 正在热更新 DSHA 任务通知与移动前端插件..."

if [ ! -d "$ROOTFS/root" ]; then
    echo "⚠️ 错误: 未检测到有效的 rootfs 目录 ($ROOTFS)，跳过补丁应用。"
    exit 1
fi

NOTIFIER_DIR="$ROOTFS/root/dsha-task-notifier/lib"
MOBILE_DIR="$ROOTFS/root/dsha-web-mobile/lib"
mkdir -p "$NOTIFIER_DIR" "$MOBILE_DIR"

echo "  -> 写入已修复的 dsha-task-notifier/lib/index.js ..."
cat << EOF_B64_NOTIFIER | base64 -d > "$NOTIFIER_DIR/index.js"

EOF_B64_NOTIFIER
chmod 644 "$NOTIFIER_DIR/index.js"

echo "  -> 写入已修复的 dsha-web-mobile/lib/index.js ..."
cat << EOF_B64_WEB_INDEX | base64 -d > "$NOTIFIER_DIR/../index.js_tmp" 2>/dev/null || true
cat << EOF_B64_WEB_INDEX | base64 -d > "$MOBILE_DIR/index.js"

EOF_B64_WEB_INDEX
chmod 644 "$MOBILE_DIR/index.js"

echo "  -> 写入已修复的 dsha-web-mobile/lib/client.js ..."
cat << EOF_B64_WEB_CLIENT | base64 -d > "$MOBILE_DIR/client.js"

EOF_B64_WEB_CLIENT
chmod 644 "$MOBILE_DIR/client.js"

# 补齐安装立牌凭证
touch "$ROOTFS/root/dsha-task-notifier-installed"
touch "$ROOTFS/root/dsha-web-mobile-installed"

# 补齐/核验 Web Profile 与全局软链接
PROFILE_NM="$ROOTFS/root/.dsh/profiles/web/node_modules"
GLOBAL_NM="$ROOTFS/usr/local/lib/node_modules"
mkdir -p "$PROFILE_NM" "$GLOBAL_NM" 2>/dev/null || true

ln -sfn "/root/dsha-task-notifier" "$PROFILE_NM/dsh-task-notifier" 2>/dev/null || true
ln -sfn "/root/dsha-web-mobile" "$PROFILE_NM/dsh-web-mobile" 2>/dev/null || true
ln -sfn "/root/dsha-task-notifier" "$GLOBAL_NM/dsh-task-notifier" 2>/dev/null || true
ln -sfn "/root/dsha-web-mobile" "$GLOBAL_NM/dsh-web-mobile" 2>/dev/null || true

# 语法卫士检测 (如果宿主环境中存在 node 或通过 chroot 检测)
if chroot "$ROOTFS" /usr/local/bin/node --version >/dev/null 2>&1; then
    echo "  -> 执行插件语法安全断言..."
    chroot "$ROOTFS" /usr/local/bin/node --check /root/dsha-task-notifier/lib/index.js
    chroot "$ROOTFS" /usr/local/bin/node --check /root/dsha-web-mobile/lib/index.js
    chroot "$ROOTFS" /usr/local/bin/node --check /root/dsha-web-mobile/lib/client.js
    echo "  ✓ 现场语法检测 100% 通过！"
fi

echo "✓ 增量补丁应用成功：任务通知防误弹与Web审批弹窗自愈已生效！"
